        'zabbix_blurb' => 'Moniteringsprobleme maak self voorvalle oop, herhalings word daarby gevoeg, en herstel los hulle op.',
        'zabbix_intro' => 'Wanneer Zabbix \'n probleem vind - \'n skyf wat vol word, \'n bediener wat nie antwoord nie - skep dit hier \'n voorval, gekoppel aan daardie bediener in die CMDB. As dit dieselfde probleem weer meld, gaan dit op dieselfde kaartjie. Wanneer die probleem verdwyn, word die kaartjie opgelos.',
        'zabbix_direction' => 'Zabbix roep FreeITSM - FreeITSM koppel nooit aan Zabbix nie, dus het dit nie Zabbix se adres of \'n Zabbix-wagwoord nodig nie. Alles wat Zabbix nodig het, is hieronder.',
        'zabbix_not_ready' => 'Voer eers Stelsel → Databasisverifikasie uit: dit skep die tabel waarin hierdie integrasie sy gebeurtenislogboek hou.',
        'zabbix_connect' => 'Koppel Zabbix',
        'zabbix_connect_body' => 'Zabbix stuur elke waarskuwing na die adres hieronder met die geheime teken. Gaan in Zabbix na Alerts → Media types → Create media type, kies Webhook, noem dit FreeITSM, plak die parameters en die skrip hieronder, en voeg dit dan by \'n gebruiker en by \'n aksie onder Alerts → Actions → Trigger actions. Merk "Recovery operations" in die aksie, anders word kaartjies nooit opgelos nie.',
        'zabbix_endpoint' => 'FreeITSM se adres (gee dit aan Zabbix)',
        'zabbix_import' => 'Vinnigste: voer dit in Zabbix in',
        'zabbix_import_body' => 'Laai die mediatipe af met alles ingevul - die adres hierbo, jou teken, die skrip en die drie boodskapsjablone - gaan dan in Zabbix na Alerts → Media types → Import en kies die lêer. Gee dit daarna aan \'n gebruiker en voeg \'n aksie by (stap 4 van die gids).',
        'zabbix_import_download' => 'Laai af vir Zabbix-invoer',
        'zabbix_import_needs_token' => 'Maak eers \'n teken - die lêer dra dit.',
        'zabbix_by_hand' => 'Of stel dit met die hand op',
        'zabbix_token' => 'Teken',
        'zabbix_token_none' => 'Nog geen teken nie - maak een om die integrasie aan te skakel.',
        'zabbix_token_make' => 'Maak teken',
        'zabbix_token_rotate' => 'Nuwe teken',
        'zabbix_rotate_confirm' => 'Maak \'n nuwe teken? Die ou een hou dadelik op werk, dus sal Zabbix misluk totdat jy die nuwe een in sy mediatipe plak.',
        'zabbix_params' => 'Mediatipe-parameters',
        'zabbix_params_hint' => 'Skrap die parameters wat Zabbix vir \'n nuwe webhook invul (URL, HTTPProxy, To, Subject, Message) - hulle behoort aan sy voorbeeldskrip, nie hierdie een nie. Voeg dan elke reël hier as \'n parameter by: die naam links, die waarde regs. http_proxy bly leeg tensy jou Zabbix-bediener FreeITSM net deur \'n proksi kan bereik. Die waardes in krulhakies is Zabbix-makro\'s - laat hulle soos hulle is. Die url-reël gee elke kaartjie \'n skakel terug na die probleem in Zabbix; dit het die makro {$ZABBIX.URL} nodig, gestel op jou Zabbix-webadres (Zabbix: Administration → Macros). Daarsonder het die kaartjies eenvoudig geen skakel nie.',
        'zabbix_script' => 'Mediatipe-skrip',
        'zabbix_copy' => 'Kopieer',
        'zabbix_copied' => 'Gekopieer.',
