        'threecx_blurb' => 'Sien wie bel voordat jy antwoord, hou elke oproep op die beller se kaartjie, en skakel \'n nommer met een klik.',
        'threecx_intro' => 'Wanneer \'n oproep lui, vra 3CX vir FreeITSM aan wie die nommer behoort en wys die beller se naam - en maak hul kaartjie vir die ontleder oop. Wanneer die oproep eindig, word dit op daardie kaartjie aangeteken, geskryf deur die ontleder wat dit geneem het. Foonnommers op kaartjies en mense kan ook deur 3CX uitskakel.',
        'threecx_direction' => '3CX roep FreeITSM - FreeITSM koppel nooit aan 3CX nie, dus het dit nie jou foonstelsel se adres of \'n 3CX-wagwoord nodig nie. Alles wat 3CX nodig het, is in die sjabloon hieronder.',
        'threecx_not_ready' => 'Voer eers Stelsel → Databasisverifikasie uit: dit skep die tabel waarin hierdie integrasie sy oproeplogboek hou.',
        'threecx_connect' => 'Koppel 3CX',
        'threecx_connect_body' => '3CX koppel aan FreeITSM deur \'n CRM-sjabloon. Maak \'n teken, laai die sjabloon af, en laai dit op in die 3CX Admin Console onder Integrations → CRM. 3CX moet die adres hieronder kan bereik.',
        'threecx_endpoint' => 'FreeITSM se adres, soos 3CX dit sal bereik',
        'threecx_reach_hint' => 'Dit begin as jou publieke basis-URL. 3CX is dikwels in die wolk, dus moet dit \'n adres wees wat die internet kan bereik. Verander dit hier en die aflaai volg.',
        'threecx_token' => 'Teken',
        'threecx_token_none' => 'Nog geen teken nie - maak een om die integrasie aan te skakel.',
        'threecx_token_make' => 'Maak',
        'threecx_token_rotate' => 'Vervang',
        'threecx_rotate_confirm' => 'Maak \'n nuwe teken? 3CX hou op om FreeITSM te bereik totdat jy die sjabloon weer oplaai (of die nuwe teken daarin plak).',
        'threecx_copy' => 'Kopieer',
        'threecx_copied' => 'Gekopieer.',
        'threecx_download' => 'Laai af',
        'threecx_download_body' => 'Die sjabloon, gereed om op te laai: die adres, hierdie teken, die bellernasoek en die oproepverslag. Dit hou die teken, dus hou die lêer vir jouself.',
        'threecx_download_needs_token' => 'Maak eers \'n teken - die sjabloon dra dit.',
        'threecx_calls_h' => 'Oproepe op kaartjies',
        'threecx_rule' => 'Op watter kaartjie \'n oproep gaan',
        'threecx_rule_latest' => 'Die beller se mees onlangs bygewerkte oop kaartjie',
        'threecx_rule_only_one' => 'Slegs wanneer die beller presies een oop kaartjie het',
        'threecx_rule_log_only' => 'Geen - oproepe word net hieronder gelys',
        'threecx_rule_hint' => 'Die kaartjie wat 3CX vir die ontleder oopmaak wanneer die oproep lui, volg dieselfde keuse.',
        'threecx_create' => 'Maak \'n nuwe kaartjie oop vir \'n oproep van iemand sonder \'n oop kaartjie',
        'threecx_create_unknown' => 'Ook vir nommers wat niemand in FreeITSM het nie',
        'threecx_create_hint' => 'Slegs vir inkomende oproepe (beantwoord of gemis). Die ontleder wat die oproep geneem het, word toegewys. \'n Onbekende beller word as "Caller" en hul nommer liasseer, gereed om aan die regte persoon gekoppel te word.',
        'threecx_fallback' => 'Skryf notas as, wanneer die 3CX-gebruiker nie \'n ontleder is nie',
        'threecx_fallback_hint' => '\'n Nota word geskryf deur die ontleder wie se e-pos by die 3CX-gebruiker pas wat die oproep geneem het. Wanneer niemand pas nie - \'n ontvangsdame, \'n gedeelde foon - word dit in plaas daarvan deur hierdie ontleder geskryf, met \'n vermelding van wie dit geneem het. Met niemand gekies nie, word daardie oproepe net hieronder gelys.',
        'threecx_nobody' => 'Niemand',
        'threecx_company' => 'Maatskappy vir kaartjies van onbekende nommers',
        'threecx_company_hint' => '\'n Bekende beller se kaartjie gaan in hul eie maatskappy.',
        'threecx_team' => 'Span vir nuwe kaartjies',
        'threecx_origin' => 'Oorsprong vir nuwe kaartjies',
        'threecx_none' => 'Geen',
        'threecx_dial_h' => 'Klik-om-te-bel',
        'threecx_dial_body' => 'Foonnommers op kaartjies, op Kaartjies → Gebruikers en op Mense kry \'n Bel-knoppie wat deur jou foon skakel. Dit maak op die ontleder se eie rekenaar oop, waar hulle reeds by 3CX aangemeld is, dus het FreeITSM nooit hul uitbreiding nodig nie.',
        'threecx_dial' => 'Skakeladres',
        'threecx_dial_hint' => 'Plaas {number} waar die nommer hoort. Vir die 3CX-webkliënt: https://your-pbx.3cx.com/webclient/#/call?phone={number}. Vir die 3CX-lessenaartoepassing (of enige sagtefoon): tel:{number}. Los dit leeg om Bel-knoppies af te skakel.',
        'threecx_saved' => 'Gestoor.',
        'threecx_try' => 'Probeer \'n oproep',
        'threecx_try_body' => 'Sien wat \'n oproep met hierdie instellings sou doen - wie die beller is, op watter kaartjie dit sou gaan en deur wie die nota geskryf sou word. Niks word geskryf nie: dit is dieselfde besluit wat \'n egte oproep neem, net beskryf.',
        'threecx_try_number' => 'Foonnommer',
