        'configured' => 'Opgestel',
        'not_configured' => 'Nie opgestel nie',
        'tika_blurb' => 'Lees die teks binne PDF\'s, ouer Office-lêers en geskandeerde dokumente sodat hulle deursoek kan word.',
        'tika_intro' => 'Wys FreeITSM na \'n dokumentleesdiens. Word-, Excel-, PowerPoint- en gewone tekslêers word reeds sonder hierdie deursoek; Tika voeg die formate by wat FreeITSM nie self kan lees nie.',
        'tika_security_title' => 'Hou dit van die netwerk af',
        'tika_security_body' => 'Tika het geen wagwoord en geen verifikasie van enige aard nie: enigiets wat dit kan bereik, sal enige lêer lees wat daarheen gestuur word. Laat dit so loop dat slegs hierdie bediener daarmee kan praat — gebind aan 127.0.0.1, of op \'n private houernetwerk — en moet nooit sy poort aan die internet blootstel nie.',
        'tika_connection' => 'Verbinding',
        'tika_url_label' => 'Adres',
        'tika_url_hint' => 'Byvoorbeeld http://127.0.0.1:9998. Los dit leeg om dokumentlees af te skakel; PDF\'s sal eenvoudig as onleesbaar gelys word.',
        'tika_timeout_label' => 'Uitteltyd (sekondes)',
        'tika_timeout_hint' => 'Hoe lank om vir een dokument te wag. Geskandeerde bladsye neem baie langer as gewone teks.',
        'tika_test' => 'Toets verbinding',
        'tika_test_ok' => 'Gekoppel. {detail}',
        'tika_test_bad' => 'Kon dit nie bereik nie. {detail}',
        'tika_saved' => 'Gestoor. Nuwe aanhangsels sal van nou af gelees word.',
        'tika_saved_off' => 'Gestoor. Dokumentlees is afgeskakel.',
