        'tika_running' => 'Laat een loop',
        'tika_running_body' => 'FreeITSM installeer of bestuur nie Tika nie. Laat dit self loop waar dit jou pas, en sit sy adres hierbo. Met Docker is dit een opdrag:',
        'tika_image_note' => 'Gebruik die -full-beeld. Die kleiner een het geen karakterherkenning nie, so geskandeerde dokumente sal leeg terugkom.',
        'slack_workspaces' => 'Slack-werkruimtes',
        'slack_workspaces_desc' => 'Elkeen is \'n Slack-toepassing wat jy in jou eie werkruimte installeer. FreeITSM sien nooit jou Slack-verkeer nie — die toepassing praat reguit met hierdie bediener.',
        'slack_col_channel' => 'Dophou',
        'slack_any_channel' => 'Enige kanaal waarheen dit genooi is',
        'slack_empty' => 'Nog geen Slack-werkruimtes nie. Voeg een by, en haal dan sy toepassing van Slack af.',
        'slack_needs_setup' => 'Moet opgestel word',
        'slack_add_title' => 'Voeg \'n Slack-werkruimte by',
        'slack_edit_title' => 'Wysig Slack-werkruimte',
        'slack_name_hint' => 'Word net in hierdie lys gebruik, en as die naam van die Slack-toepassing wat jy skep.',
        'slack_name_required' => 'Gee hierdie werkruimte \'n naam.',
        'slack_unchanged' => 'Onveranderd — los leeg om dit te behou',
        'slack_bot_token' => 'Bot-gebruiker OAuth-teken',
        'slack_bot_token_hint' => 'Van jou Slack-toepassing, onder OAuth &amp; Permissions. Begin met xoxb-. Jy kry dit nadat die toepassing geïnstalleer is, so los dit leeg met die eerste stoor.',
        'slack_signing_secret' => 'Handtekeninggeheim',
        'slack_signing_secret_hint' => 'Van jou Slack-toepassing, onder Basic Information. Dit is hoe FreeITSM bewys dat \'n boodskap werklik van Slack af kom, so niks word aanvaar voordat dit gestel is nie.',
        'slack_watch_channel' => 'Hou net hierdie kanaal dop',
        'slack_watch_channel_hint' => '\'n Slack-kanaal-ID soos C08ABCDEF. Los leeg om \'n kaartjie te skep vanuit elke kanaal waarheen die toepassing genooi is — wat op \'n besige kanaal \'n kaartjie per boodskap beteken, so die meeste mense noem hier een hulpkanaal.',
        'slack_company_shared' => 'Gedeel — besluit volgens sender',
        'slack_company_hint' => 'Pen hierdie werkruimte aan een maatskappy vas, of laat dit gedeel en laat die sender besluit.',
        'slack_delete_confirm' => 'Skrap die Slack-werkruimte “{name}”? Kaartjies wat reeds daaruit geskep is, behou hul geskiedenis; slegs nuwe boodskappe hou op om aan te kom.',
        'slack_diag_title' => 'Slack-gesondheidskontrole',
        'slack_diag_desc' => 'Kontroleer alles wat stilweg verkeerd kan wees — nie net of die teken werk nie. Elke resultaat sê wat daaraan gedoen moet word.',
        'slack_diag_running' => 'Kontroleer tans — dit praat met Slack en met jou eie openbare adres, so gee dit \'n paar sekondes…',
        'slack_diag_rerun' => 'Voer weer uit',
        'slack_diag_all_ok' => 'Alles is in orde. Boodskappe wat in die dopgehoue Slack-kanaal geplaas word, sal kaartjies word, en antwoorde sal terug in die gesprek gaan.',
        'slack_diag_some_warn' => 'Werk, met iets wat die moeite werd is om te weet. Niks hieronder keer dat kaartjies aankom nie, maar dit is die moeite werd om te lees.',
        'slack_diag_some_fail' => 'Iets is verkeerd en boodskappe sal nie aankom nie. Die gefaalde kontroles hieronder sê wat om te doen.',
        'slack_app_title' => 'Die Slack-toepassing',
        'slack_copy_manifest' => 'Kopieer die manifes',
        'slack_scopes_heading' => 'Wat die toepassing mag doen',
        'slack_scopes_desc' => 'Jou Slack-administrateur sal hierdie lys sien wanneer die toepassing goedgekeur word. Niks hier laat dit toe om kanale te skep, mense te nooi of iewers te plaas waarheen dit nie genooi is nie.',
        'slack_step1' => 'Gaan in Slack na <strong>api.slack.com/apps</strong> en kies <strong>Create New App → From a manifest</strong>. Kies die werkruimte waarin jy die dienstoonbank wil hê.',
        'slack_step2' => 'Plak hierdie manifes. Dit stel die naam, die toestemmings en die adres waarheen Slack boodskappe stuur, so daar is niks om met die hand te merk nie.',
        'slack_step3' => 'Klik <strong>Install to Workspace</strong> en keur dit goed. Kopieer dan die <strong>Bot User OAuth Token</strong> en die <strong>Signing Secret</strong> terug na die Wysig-vorm hier — Slack sal die teken nie weer wys nie. <strong>As Slack \'n geel &ldquo;Reinstall to Workspace&rdquo;-banier wys, klik dit eerste</strong> — anders ontbreek die meeste van die teken se toestemmings en kaartjies kom sonder die naam van die sender aan.',
        'slack_step4' => 'Kontroleer dat die versoek-URL hieronder ooreenstem met wat Slack onder <strong>Event Subscriptions</strong> wys. Slack verifieer dit sodra jy die toepassing stoor, so hierdie bediener moet vanaf die internet bereikbaar wees.',
        'slack_step5' => 'Nooi die toepassing in Slack na die kanaal wat jy wil hê dit moet dophou: <strong>/invite @YourApp</strong>. Dit kan nie \'n kanaal lees waarin dit nie is nie.',
    ],
