        'no_ai_later' => 'Voeg meer by wanneer jy wil: \'n <strong>inbeddingsleutel</strong> maak dit beter met losweg gestelde vrae, en \'n <strong>klets-KI</strong> skryf die antwoord in \'n sin of twee, in die vraesteller se eie taal - albei hieronder.',
