        'step_dns_body' => 'Die rekenaars moet weet dat {host} {ip} beteken. Die beste manier is \'n DNS-rekord op jou netwerk se DNS-bediener (op \'n Windows-domein in DNS Manager; op \'n klein netwerk dikwels in die router):',
        'step_dns_record' => 'Tipe A, naam {host}, adres {ip}',
        'step_dns_hosts' => 'Sonder \'n DNS-bediener, voeg hierdie reël by die hosts-lêer op elke rekenaar ({path} op Windows, {path_mac} op \'n Mac):',
        'step_dns_no_ip' => 'Vul die bediener-IP-adres hierbo in om die presiese rekord te sien wat geskep moet word.',
        'step_ca_title' => 'Installeer die owerheidsertifikaat op elke rekenaar',
        'step_ca_body' => 'Dit sê vir die rekenaars om die sertifikaat te vertrou. Dit hoef net een keer per rekenaar gedoen te word, en weer slegs as jy die naam of IP verander.',
        'download' => 'Laai af',
        'step_ca_windows' => 'Windows: dubbelklik die lêer, kies Install Certificate, kies Local Machine, dan Place all certificates in the following store, en kies Trusted Root Certification Authorities.',
        'step_ca_gpo' => 'Baie Windows-rekenaars op \'n domein: voer die lêer een keer in Group Policy in, onder Computer Configuration → Policies → Windows Settings → Security Settings → Public Key Policies → Trusted Root Certification Authorities. Intune kan dit as \'n Trusted certificate-profiel uitstuur.',
        'step_ca_mac' => 'Mac: dubbelklik die lêer om dit by Keychain Access te voeg, maak dit daar oop, en stel When using this certificate op Always Trust.',
        'step_ca_firefox' => 'Firefox op Windows gebruik die Windows-sertifikate outomaties. As dit steeds waarsku, stel security.enterprise_roots.enabled op true in about:config.',
        'step_ca_safe' => 'Hierdie owerheid kan net vir {host} instaan, niks anders nie, so om dit te installeer laat dit nie toe om as enige ander webwerf voor te gee nie.',
        'step_restart_title' => 'Herbegin die houer',
        'step_restart_body' => 'Voer {cmd} uit in die vouer wat jou docker-compose.yml bevat.',
        'step_restart_done' => 'Klaar: die houer gebruik hierdie sertifikaat.',
        'step_open_title' => 'Maak FreeITSM oor HTTPS oop',
        'step_open_body' => 'Gaan na {url}. As dit nie laai nie, kontroleer dat jou docker-compose.yml poort 443 publiseer (die standaardlêer koppel dit aan 8443). As jy dit verander het, gebruik jou poort.',
        'proxy_heading' => 'Agter \'n trugproksi',
        'proxy_intro' => 'As \'n trugproksi, lasbalanseerder of Cloudflare Tunnel voor FreeITSM sit, bereik elke versoek FreeITSM vanaf die proksi. Tensy jy FreeITSM vertel watter adres die proksi is, teken dit die proksi se adres vir almal aan: in Verslagdoening → Logboeke, in die ouditspore, en wanneer \'n API key kontroleer watter adresse dit toelaat.',
        'proxy_off_title' => 'Af',
        'proxy_off_body' => 'FreeITSM teken die adres aan waarvandaan elke verbinding kom. Dit is reg wanneer mense direk met FreeITSM verbind, en verkeerd agter \'n proksi - gebruik Toets hieronder om te sien watter een jy het.',
        'proxy_on_title' => 'Aan',
        'proxy_on_body' => 'Die regte adres word uit die {header}-kopstuk geneem, maar net op versoeke wat van {list} af kom.',
        'proxy_refused_title' => 'Gestel, maar nie van krag nie',
        'proxy_refused_body' => 'TRUSTED_PROXIES is gestel op {list}, maar dit is van die hand gewys toe die houer begin het, so FreeITSM teken die adres aan waarvandaan elke verbinding kom. Voer {cmd} uit om te sien hoekom.',
        'proxy_wide_title' => 'Waarskuwing: hierdie instelling is te wyd',
        'proxy_wide_body' => '{ranges} dek meer as een proksi. Elke masjien daarin kan beweer dit is enige adres wat dit wil. Verander TRUSTED_PROXIES na die proksi se eie adres en herbegin die houer.',
        'proxy_danger_title' => 'Wat \'n verkeerde instelling doen - lees dit voor jy verander',
        'proxy_danger_wide' => 'Te wyd - die gevaarlike fout. FreeITSM glo die adres in die proksi se kopstuk net op versoeke van die adresse wat jy lys, omdat enigiemand daardie kopstuk kan skryf. Lys \'n reeks soos {example} of die hele Docker-netwerk, en enige masjien daarin kan beweer dit is enige adres: dit kan \'n valse adres in die aanmeldlogboek en die ouditspore plaas, en verby \'n API key kom wat net sekere adresse toelaat. Lys net die proksi se eie adres.',
        'proxy_danger_missing' => 'Nie gestel nie, wanneer daar \'n proksi is. Niks breek nie, maar elke aanmelding en elke verandering word van die proksi se adres aangeteken, so die logboeke kan nie mense uitmekaar hou nie - en \'n API key se toegelate adresse kan net die proksi noem, wat enigiemand toelaat wat daardeur kom.',
        'proxy_danger_wrong' => 'Die verkeerde adres. Die kopstuk word geïgnoreer, so jy is terug by almal wat as die proksi aangeteken word. Toets wys dit dadelik.',
        'proxy_how' => 'Dit word in docker-compose.yml gestel, nie op hierdie bladsy nie, en tree in werking wanneer die houer herbegin (docker compose up -d):',
        'proxy_how_cf' => 'Vir \'n Cloudflare Tunnel, stel ook {setting}. Verskeie proksi\'s: skei hulle met spasies.',
        'proxy_test_heading' => 'Toets.',
        'proxy_test_intro' => 'Wys die adres wat FreeITSM nou net vir jou aangeteken het, en wat dit beteken. Dit verander niks nie.',
        'proxy_test' => 'Toets',
        'proxy_testing' => 'Toets tans...',
        'proxy_test_failed' => 'Die toets kon nie loop nie.',
        'proxy_recorded' => 'FreeITSM het jou adres aangeteken as',
        'verdict_direct' => 'Jy verbind direk met FreeITSM - geen proksi-kopstuk het aangekom nie - so daar is niks om te stel nie. As jy weet daar is \'n proksi voor, voeg dit nie \'n kopstuk by nie: gaan sy instellings na.',
        'verdict_off_proxy' => '\'n Proksi is voor FreeITSM (hierdie versoek het {headers} gedra), en FreeITSM teken die proksi se adres, {ip}, vir almal aan. Om regte adresse aan te teken, voeg dit by die toepassing se omgewing in docker-compose.yml:',
        'proxy_suggest_then' => 'Dit is die proksi se adres soos FreeITSM dit sien - lys dit alleen, niks wyer nie. Voer dan docker compose up -d uit en toets weer.',
        'verdict_working' => 'Werk: hierdie adres het van die proksi se kopstuk gekom. Gaan na dit werklik jou rekenaar se adres is - op Windows wys ipconfig dit; van buite jou netwerk, jou openbare adres. As dit die proksi se adres of 127.0.0.1 wys, is iets verkeerd.',
        'verdict_too_wide' => 'Nie veilig nie: jou eie adres, {ip}, is binne die reeks wat FreeITSM as die proksi vertrou, so FreeITSM kan jou nie van die proksi onderskei nie - en enigiemand anders in daardie reeks kan enige adres beweer. Verander TRUSTED_PROXIES na die proksi se eie adres en herbegin die houer.',
        'verdict_still_proxy' => 'Werk nie: die adres wat aangeteken is, is die proksi self, so die proksi stuur nie die {header}-kopstuk nie. Laat die proksi {header} byvoeg, of stel TRUSTED_PROXY_HEADER op die kopstuk wat dit wel stuur.',
        'verdict_refused' => 'Die instelling is nie van krag nie (sien hierbo), so FreeITSM teken die adres aan waarvandaan elke verbinding kom. Maak eers die instelling reg, en toets dan weer.',
        'proxy_headers_seen' => 'Proksi-kopstukke op hierdie versoek:',
        'proxy_headers_none' => 'Geen proksi-kopstukke op hierdie versoek nie.',
    ],
