        'needs_db' => '\'n Databasisopdatering is eers nodig',
        'needs_db_desc' => 'Voer Stelsel → Databasisverifikasie uit, kom dan terug na hierdie bladsy.',
        'conn_heading' => 'Verbinding',
        'conns_heading' => 'Verbindings',
        'conns_desc' => 'Hoe FreeITSM gebeurtenisse in ontleders se eie kalenders skryf. Voeg soveel by as wat jy nodig het - Microsoft 365, een of meer CalDAV-bedieners, of albei. Elke ontleder kies waarheen hul werk gaan onder <strong>Voorkeure &rarr; My werkkalender</strong>.',
