        'provider_caldav_short' => 'CalDAV',
        'provider_caldav' => '\'n CalDAV-bediener (Nextcloud, Baïkal, Radicale, iCloud, Fastmail…)',
        'caldav_desc' => 'FreeITSM skryf elke ontleder se geskeduleerde werk in \'n kalender op jou CalDAV-bediener, <strong>aangemeld as daardie ontleder</strong>. \'n CalDAV-bediener het geen manier vir een rekening om in almal se kalenders te skryf nie, so daar is hier geen wagwoord nie: elke ontleder meld aan en kies hul kalender onder <strong>Voorkeure &rarr; My werkkalender</strong>.',
        'server_url' => 'Bedieneradres',
        'server_url_hint' => 'Die bediener se DAV-adres, nie sy webbladsy nie. Baïkal: <code>https://server/dav.php/</code> &middot; Nextcloud: <code>https://server/remote.php/dav/</code> &middot; Radicale: <code>https://server/</code>. Ontleders kan net kalenders op hierdie bediener kies.',
