        'caldav_auth_hint' => 'Los dit op Outomaties tensy jy \'n rede het om nie te doen nie. \'n Standaard Baïkal wil Digest hê eerder as Basic, en Outomaties vra die bediener watter een dit aanbied.',
        'caldav_probe' => 'Probeer \'n aanmelding (opsioneel, slegs vir hierdie toets gebruik en nie gestoor nie)',
