        'caldav_no_notify' => 'CalDAV-bedieners stuur nie veranderingskennisgewings nie, so veranderinge wat in \'n kalender gemaak word, kom aan wanneer die geskeduleerde taak loop.',
        'people_desc_caldav' => 'Elke ontleder meld by die CalDAV-bediener aan en kies hul eie kalender onder Voorkeure. \'n Administrateur kan dit nie vir hulle kies nie, omdat net die ontleder die wagwoord het wat dit bereik.',
        'no_account' => 'Nie aangemeld nie',
        'switch_title' => 'Verander waarheen hierdie verbinding skryf?',
        'switch_confirm' => 'Dit neem die {mapped} gebeurtenis(se) terug wat hierdie verbinding in ontleders se kalenders geplaas het, en skakel kalendersinkronisasie af vir die {pushing} ontleder(s) wat dit gebruik, sodat elkeen dit weer kan opstel. Ontleders op ander verbindings, en intekeningskakels, word nie geraak nie.',
        'switch_ok' => 'Verander',
        'switch_done' => 'Gestoor. Kalendersinkronisasie is teruggestel vir die ontleders op hierdie verbinding.',
        'perm_title' => 'Voordat dit sal werk',
        'perm_body' => 'Die programregistrasie het <strong>Calendars.ReadWrite</strong> nodig as \'n <strong>Application</strong>-toestemming (nie Delegated nie — dit is aparte lyste in Azure), met administrateurtoestemming verleen. Wees bewus dat hierdie toestemming FreeITSM toelaat om na <strong>elke posbus in die huurder</strong> te skryf. As dit meer is as wat jy wil verleen, beperk die program tot \'n pos-geaktiveerde sekuriteitsgroep van jou ontleders met \'n Application Access Policy in Exchange Online.',
        'name' => 'Naam',
        'source_mailbox' => 'Leen die bewyse van \'n posbus',
        'source_own' => 'Voer bewyse in',
        'mailbox' => 'Posbus',
        'no_mailboxes' => 'Geen Microsoft-posbus op hierdie stelsel het Azure-bewyse om te leen nie, so voer dit hieronder in. Dit is normaal as jou ontleders se kalenders in \'n ander huurder is as jou inname-posbusse, of as jou inname glad nie Microsoft is nie.',
        'tenant_id' => 'Directory (tenant) ID',
        'client_id' => 'Application (client) ID',
        'client_secret' => 'Kliëntgeheim',
        'secret_note' => 'Die geheim word geënkripteer gestoor en nooit weer gewys nie. Los dit leeg wanneer jy wysig om die een te behou wat reeds gestoor is.',
        'test' => 'Toets',
        'testing' => 'Toets tans…',
        'probe' => 'Kontroleer ook dat hierdie posbus bereik kan word (opsioneel)',
        'saved' => 'Gestoor',
        'last_error' => 'Die laaste poging het misluk met:',
