        'test_failed' => 'Kon nie koppel nie.',
        'test_failed_hint' => 'Kontroleer dat die kliëntgeheim nie verval het nie, en dat Calendars.ReadWrite onder Application-toestemmings gelys is met administrateurtoestemming verleen.',
        'probe_ok' => '{addr} het \'n kalender waarin FreeITSM kan skryf.',
        'probe_bad' => 'Geen kalender gevind vir {addr} nie. Kontroleer dat die adres \'n werklike posbus in hierdie huurder is — \'n ontleder se FreeITSM-e-posadres is nie altyd hul posbusadres nie.',
        'conn_delete_confirm' => 'Skrap “{name}”?',
        'conn_delete_title' => 'Skrap hierdie verbinding?',
        'conn_delete_used' => 'FreeITSM neem die {mapped} gebeurtenis(se) terug wat hierdie verbinding in ontleders se kalenders geplaas het, en skakel kalendersinkronisasie af vir die {pushing} ontleder(s) wat dit gebruik. Ontleders op ander verbindings word nie geraak nie.',
        'conn_deleted' => 'Verbinding geskrap',
        'people_heading' => 'Met watter posbus elke ontleder sinkroniseer',
        'people_desc' => 'Standaard gebruik FreeITSM die e-posadres op die ontleder se rekening, wat dikwels nie hul posbus is nie &mdash; \'n plaaslike rekening, of \'n gidsinvoer op grond van iets anders. Oorheers dit hier. Ontleders kies <em>of</em> hul werk gesinkroniseer word; slegs \'n administrateur kies <em>waarheen</em> dit gaan.',
        'col_analyst' => 'Ontleder',
        'col_status' => 'Deur die ontleder gekies',
        'check_save' => 'Kontroleer en stoor',
        'mode_off' => 'Af',
        'mode_push' => 'Sinkroniseer',
        'mode_feed' => 'Ingeteken',
        'mode_error' => 'Laaste sinkronisasie het misluk',
        'tasks_work' => 'Take: beplan',
        'tasks_due' => 'Take: sperdatums',
        'tasks_both' => 'Take: albei',
        'tasks_note' => 'Hierdie ontleder het gekies om hul take in te sluit. Hulle kies dit self onder Voorkeure; dit kan nie hier vir hulle gestel word nie.',
        'saved_unverified' => 'Gestoor. Die adres kon nie gekontroleer word nie omdat die verbinding nie werk nie — toets dit hierbo.',
        'inbound_heading' => 'Veranderinge in die kalender gemaak',
        'inbound_desc' => 'Skuif een van hierdie afsprake in Outlook en die kaartjie volg. Dit vereis dat die <code>cron/calendar_sync_pull.php</code>-taak loop &mdash; elke 5 minute is redelik. Sonder dit is die sinkronisasie eenrigting, wat presies is hoe dit vandag werk.',
        'accept_deletes' => 'Om die afspraak te skrap, haal die kaartjie van die skedule af',
        'notify_url' => 'Kennisgewing-URL (opsioneel)',
        'notify_url_note' => 'Los leeg om op die geskeduleerde kontrole alleen staat te maak, wat heeltemal goed is &mdash; veranderinge kom dan binne \'n paar minute aan. Vul dit in en Microsoft sê vir FreeITSM die oomblik iets verander, so dit kom in sekondes aan. Dit moet \'n <strong>HTTPS-adres wees wat Microsoft vanaf die internet kan bereik</strong>, wat op <code>/api/calendar/graph_notify.php</code> eindig. Die geskeduleerde taak is steeds in elk geval nodig: dit hernu die intekeninge, en vang alles wat \'n gemiste kennisgewing andersins sou verloor.',
        'notify_suggest' => 'Gebruik hierdie adres',
        'notify_suggest_note' => 'Ingevul vanaf die adres wat jy nou gebruik. Kontroleer dat dit van buite bereikbaar is — agter \'n instaanbediener of \'n tonnel is dit dikwels nie, en \'n verkeerde een misluk met \'n boodskap oor validering eerder as oor die adres.',
        'notify_saved' => 'Die geskeduleerde taak sal die intekeninge met sy volgende lopie skep of bywerk.',
        'notify_active' => '{n} intekening(e) aktief',
        'health_checked' => 'Kalenders is laas {n} gelede gekontroleer.',
        'health_never' => 'Kalenders is nog nooit gekontroleer nie.',
        'health_stale_note' => 'Veranderinge in Outlook kom aan wanneer die geskeduleerde taak loop, so dit beteken gewoonlik dat dit gestop het &mdash; kontroleer dat <code>cron/calendar_sync_pull.php</code> steeds volgens sy skedule loop. Dit is ook wat die intekeninge hernu, so kennisgewings stop \'n paar dae nadat dit doen. As jy dit doelbewus minder dikwels as elke halfuur laat loop, is dit te verwagte.',
        'health_subs' => 'Kennisgewings: {n} van {total} ingeteken.',
        'health_just_now' => 'minder as \'n minuut',
        'health_mins' => '{n} minuut/minute',
        'health_hours' => '{n} uur',
        'health_days' => '{n} dag(e)',
        'sub_ok' => 'Ingelig',
        'sub_expires' => 'Intekening hernu binne {n}',
        'sub_none' => 'Nie ingeteken nie',
        'sub_none_note' => '\'n Kennisgewingadres is gestel, maar Microsoft het niks om vir hierdie persoon te roep nie, so hul veranderinge kom net aan wanneer die geskeduleerde taak loop. Die volgende lopie sal probeer om dit te skep; as dit aanhou misluk, verskyn die rede hier.',
        'sub_lapsed' => 'Intekening het verval',
        'accept_deletes_note' => 'Standaard af. Met dit aan vind \'n ontleder wat een van hierdie op hul foon skrap, die kaartjie reeds van die skedule af wanneer hulle gaan sit &mdash; wat dikwels die punt is. Elke sodanige verandering word in die kaartjie se geskiedenis geskryf, en \'n ongewoon groot aantal skrappings in een slag word geweier eerder as gehoorsaam, aangesien dit meer waarskynlik \'n fout as \'n opdrag is. Met dit af verskyn \'n geskrapte afspraak eenvoudig weer die volgende keer as die kaartjie verander.',
        'feed_heading' => 'Intekeningskakels',
        'feed_desc' => 'Ontleders kan hul geskeduleerde werk as \'n kalenderintekeningskakel publiseer, wat met enige kalenderprogram werk. \'n Skakel is \'n geheime URL eerder as \'n aanmelding, so enigeen wat dit het, kan lees wat dit wys.',
        'feed_label' => 'Laat intekeningskakels toe',
        'feed_full' => 'Ja — insluitend kaartjie-onderwerpe',
        'feed_ref' => 'Ja — maar slegs kaartjienommers, geen onderwerpe nie',
        'feed_off' => 'Nee',
        'feed_note' => 'Ontleders kan altyd kies om minder as dit te publiseer, nooit meer nie. As jy dit afskakel, hou skakels wat reeds uitgedeel is onmiddellik op werk.',
