    'preferences' => [
        'ticket_workspace_heading' => 'Kaartjie-werkruimte',
        'ticket_workspace_label' => 'Gebruik die werkruimte',
        'ticket_workspace_desc' => 'Gebruik die werkruimte vir die kaartjies wat deur jou administrateur geaktiveer is. Skakel af om die leesruit te bly gebruik.',
        'live_heading' => 'Lewendige opdaterings',
        'live_desc' => 'Hoe gereeld \'n bladsy kyk vir veranderinge wat ander mense maak - die kaartjielys, die oop kaartjie, die takebord, die klok - en bywerk. Dit stop terwyl die oortjie op die agtergrond is en werk by sodra jy terugkom. Geld vanaf die volgende bladsy wat jy oopmaak.',
        'live_15' => 'Elke 15 sekondes (verstek)',
