        'live_0' => 'Af - ander mense se veranderinge verskyn wanneer jy verfris (nuwe pos kom steeds aan)',
        'ticket_list_heading' => 'Kaartjielys',
        'ticket_list_desc' => 'Maak kaartjies oop as \'n boodskaplys of as \'n gepagineerde werkry.',
