        'tab_general' => 'Algemeen',
        'tab_notifications' => 'Kennisgewings',
        'tab_display' => 'Vertoon',
        'tab_details' => 'My besonderhede',
        'language_heading' => 'Koppelvlaktaal',
        'language_desc' => 'Die taal wat dwarsdeur die FreeITSM-koppelvlak gebruik word. Vertalings val terug op Engels vir enige tekse wat nog nie in jou gekose taal gedek word nie. Laai die bladsy weer wanneer jy verander.',
        'saving' => 'Stoor tans…',
        'notif_heading' => 'In die klok',
        'notif_desc' => 'Watter hiervan iets in die klok bo-aan die skerm plaas. Jy word nooit oor jou eie handelinge in kennis gestel nie, en verskeie veranderinge aan dieselfde kaartjie word in een saamgegroepeer.',
        'sound_heading' => 'Kennisgewingklank',
        'sound_desc' => 'Speel \'n kort klank wanneer iets nuuts in die klok aankom, of wanneer iemand jou in die oorlogskamer noem. Af, tensy jy \'n klank kies.',
