        'selfreg_heading' => 'Selfdienregistrasie',
        'selfreg_desc' => 'Of mense hul eie selfdienportaalrekening vanaf die aanmeldbladsy kan skep. Standaard af. Wanneer aan, word aanmelding steeds met \'n e-posskakel bevestig voordat enige wagwoord gestel word.',
