        'ipban_heading' => 'IP-verbod',
        'ipban_desc' => 'Verbied outomaties IP-adresse wat herhaaldelik aanmeldpogings teen nie-bestaande of gesluite rekeninge doen. Elke verbod duur 24 uur. Ná elke verbod daal die drempel met 1 (tot by die minimum), wat herhaalde oortreders moeiliker maak om te misbruik. Stel maksimum pogings op 0 om af te skakel.',
        'first_ban' => 'Eerste verbod-drempel',
        'first_ban_hint' => 'Mislukte pogings voordat die IP die eerste keer verbied word',
        'min_threshold' => 'Minimum drempel',
