        'ipban_example_strong' => 'Voorbeeld:',
        'ipban_example_text' => 'Met maksimum 5 en minimum 2 word die eerste verbod ná 5 mislukte pogings geaktiveer, die tweede ná 4, dan 3, dan 2. Dit bly by 2 vir elke daaropvolgende verbod. Slegs pogings teen nie-bestaande gebruikersname of reeds gesluite rekeninge tel.',
        'attachments_heading' => 'Aanhangsels',
        'attachments_desc' => 'FreeITSM aanvaar slegs aanhangseltipes wat dit herken. Enigiets anders — \'n program, \'n skrip, \'n webbladsy — word nooit onder sy eie naam gestoor nie, sodat dit nie uitgevoer kan word nie.',
        'rejected_behaviour' => 'Wanneer \'n lêertipe nie aanvaar word nie',
