        'allowed_extensions' => 'Aanvaarde lêertipes',
        'allowed_extensions_hint' => 'Los leeg om alles te aanvaar wat FreeITSM as veilig beskou, insluitend nuwe tipes wat deur toekomstige opdaterings bygevoeg word. Om minder te aanvaar, lys net die uitbreidings wat jy wil hê, geskei deur kommas.',
        'allowed_extensions_ph' => 'bv. pdf, docx, xlsx, png, jpg',
        'allowed_extensions_note' => 'Jy kan hierdie lys net vernou. \'n Uitbreiding wat FreeITSM nie reeds as veilig beskou nie, word geïgnoreer, so niks wat hier getik word kan \'n program of skrip aanvaarbaar maak nie.',
        'rejected_note' => 'Hoe ook al, die kaartjie sê wat gebeur het en hoekom, sodat niemand hoef te wonder waar hul lêer heen is nie.',
        'max_attachment' => 'Grootste aanhangsel',
        'max_attachment_hint' => 'Geen enkele aanhangsel kan groter wees as dit nie - in e-pos, die portaal, kletskanale, antwoorde en aangehegte dokumente. 10 MB tensy jy dit verander.',
        'max_total' => 'Grootste e-pos',
        'max_total_hint' => 'Al die aanhangsels op een inkomende e-pos saam. 0 beteken geen limiet buiten die een hierbo nie.',
        'php_limits' => 'PHP op hierdie bediener aanvaar blaaieroplaaie tot {upload} per lêer en {post} per versoek (upload_max_filesize en post_max_size in php.ini), en het {memory} geheue om mee te werk. \'n Lêer wat PHP weier, bereik nooit FreeITSM nie, so \'n limiet bo hierdie help net vir e-pos. \'n Webbediener of instaanbediener daarvoor (nginx client_max_body_size, IIS maxAllowedContentLength) kan \'n laer limiet van sy eie stel.',
        'php_limits_warn' => 'Die grootste aanhangsel is hoër as wat PHP vanaf \'n blaaier aanvaar: verhoog ook upload_max_filesize en post_max_size in php.ini, anders sal lêers wat deur FreeITSM opgelaai word, geweier word voordat hulle aankom.',
