        'carddav_write_warning' => 'Net die besonderhede hierbo gelys word verander, en net op die kontak wat gewysig word. Alles anders op die kaart — foto, notas, verjaarsdag, volle adres, groepe — bly presies soos dit is. As iemand dieselfde besonderheid in die adresboek verander het sedert FreeITSM laas ingevoer het, word die verandering geweier eerder as om hulle s\'n te oorskryf.',
