    'webhooks' => [
        'browser_title' => 'Webhake',
        'title' => 'Webhake',
        'subtitle' => 'Uitgaande webhake &mdash; in die tou geplaas deur die <em>Stuur \'n webhaak</em>-werkvloeiaksie &mdash; word in die agtergrond met outomatiese herpogings afgelewer, sodat \'n stadige of dooie eindpunt nooit \'n kaartjie ophou nie. Hierdie bladsy wys of aflewering opgestel is, \'n oorsig van afleweringsgesondheid, en die volledige logboek waar jy elke versoek, sy antwoord kan inspekteer en enige daarvan kan herspeel.',
