        'queued_one' => '<strong>1</strong> webhaak is in die tou en wag.',
        'queued_many' => '<strong>{n}</strong> webhake is in die tou en wag.',
        'step1' => '<strong>Skeduleer die afleweringswerker om elke minuut te loop.</strong> Voer op die bediener hierdie opdrag uit vanuit \'n geskeduleerde taak (Windows Task Scheduler) of cron (Linux):',
        'step1_http' => 'Kan nie PHP vanaf die dop laat loop nie? Roep dit eerder oor HTTP aan (bv. vanaf \'n gehoste cron-diens):',
        'step2' => '<strong>Voeg die <em>Stuur \'n webhaak</em>-aksie by \'n werkvloei</strong> sodat gebeure die tou begin vul &mdash; onder <a href="{url}">Werkvloeie</a>.',
        'step3' => '<strong>Hou hierdie bladsy dop.</strong> Sodra die werker loop, word die status hierbo groen en verskyn afleweringe hieronder. Volledige opstelnotas (Windows &amp; Linux, handtekeningverifikasie) is in <a href="https://github.com/edmozley/freeitsm/wiki/Workflows" target="_blank" rel="noopener">die Werkvloeie-wiki</a>.',
        'fact_worker' => 'Werkerskrip',
