        'fact_retention' => 'Logboekbewaring',
        'fact_queued' => 'Nou in die tou',
        'days' => '{n} dae',
        'del_title' => 'Aflewering',
        'del_desc' => 'Hoe hard FreeITSM probeer om elke webhook deur te kry.',
