        'del_attempts_label' => 'Pogings voordat dit opgee',
        'del_attempts_one' => '1 poging (geen herhaalpogings)',
        'del_attempts_opt' => '{n} pogings',
        'del_attempts_help' => '\'n Mislukte poging word na 1 minuut weer probeer, dan 5 minute, 15 minute, 1 uur en 6 uur, dan elke 6 uur. Na die laaste poging word die aflewering as <strong>Dood</strong> gemerk en wag vir <em>Herspeel</em>. \'n Verandering geld vir webhooks wat van nou af in die tou geplaas word - dié wat reeds in die tou is, hou die getal waarmee hulle begin het.',
        'del_timeout_label' => 'Wag vir die eindpunt om te antwoord',
        'del_timeout_opt' => '{n} sekondes',
        'del_timeout_help' => 'Hoe lank elke poging wag voordat dit as misluk tel. Verhoog dit slegs vir \'n eindpunt wat bekend is as stadig: die werker stuur een webhook op \'n slag, so \'n lang wagtyd hou die res van die tou op. <em>Stuur toets</em> in die werkvloei-redigeerder wag hoogstens 25 sekondes.',
        'del_int_label' => 'As \'n stuur halfpad afgebreek is',
        'del_int_retry' => 'Probeer weer - die eindpunt kan dit twee keer ontvang',
        'del_int_stop' => 'Stop, en los dit vir Herspeel',
        'del_int_help' => 'As die werker middel in \'n stuur gestop word - \'n bedienerherbegin, of die geskeduleerde taak wat doodgemaak word - weet niemand of die eindpunt dit gekry het nie. Na 10 minute besleg FreeITSM dit: <strong>Probeer weer</strong> tel dit as \'n mislukte poging en probeer weer volgens die skedule hierbo; <strong>Stop</strong> merk dit dadelik Dood, sodat jy die eindpunt kan nagaan en dit self kan Herspeel. Elke stuur dra \'n <code>X-FreeITSM-Delivery</code>-kopstuk met dieselfde nommer by elke poging en by \'n Herspeel, sodat \'n ontvanger wat jy self bedryf \'n herhaling kan ignoreer. Kletsgereedskap soos Slack en Teams kan nie, en sou die boodskap twee keer wys.',
        'dp_title' => 'Databeskerming',
        'dp_desc' => 'Wat FreeITSM oor jou webhake op skyf hou, en vir hoe lank.',
        'enc_on_title' => 'Webhaak-URL\'s en handtekeninggeheime is in rus geënkripteer',
        'enc_on_body' => 'Gestoor met AES-256-GCM, in die werkvloei en in die afleweringstou. \'n Webhaak-URL is op sigself \'n geloofsbrief &mdash; enigeen wat dit het, kan na jou kanaal plaas &mdash; en die handtekeninggeheim bewys dat \'n boodskap werklik van jou af kom.',
        'enc_off_title' => 'Geen enkripsiesleutel is gekonfigureer nie &mdash; webhaak-URL\'s en handtekeninggeheime word as gewone teks gestoor',
        'enc_off_body' => 'FreeITSM enkripteer hierdie wanneer \'n enkripsiesleutellêer teenwoordig is, maar hierdie installasie het nie een nie, so hulle word soos hulle is gestoor eerder as om jou webhake heeltemal te laat misluk. Enigeen wat die databasis of \'n rugsteun daarvan kan lees, kan na jou kanale plaas en jou handtekeninge vervals. Konfigureer die enkripsiesleutel (<code>ENCRYPTION_KEY_PATH</code>) en stoor elke webhaak-werkvloei weer om die gestoorde waardes te enkripteer.',
        'ret_label' => 'Hou gestuurde loonvrag vir',
