        'ret_help' => 'Die afleweringslogboek stoor die presiese loonvrag wat gestuur is. Met die <strong>Volledige rekord</strong>-formaat is dit \'n <strong>hele kaartjie</strong> &mdash; onderwerp, versoeker, die hele lot &mdash; hier in gewone teks gekopieer. Ná hierdie aantal dae word die loonvrag- en antwoordliggame uitgevee, terwyl die aflewerings<em>rekord</em> (eindpunt, status, tydsberekening, foute) vir oudit behou word totdat die logboekbewaring hierbo ({days} dae) die ry heeltemal verwyder.',
