    'managers' => [
        'heading' => 'Bestuurders',
        'intro' => '\'n Bestuurder is iemand in die selfdienportaal wat die kaartjies kan sien wat deur die mense onder hulle bestuur geskep is - byvoorbeeld die hoof van \'n departement. Hulle kry \'n <strong>Spankaartjies</strong>-oortjie in die portaal. Die dienstoonbank word nie geraak nie.',
        'needs_verify' => 'Voer eers Stelsel → Databasisverifikasie uit. Totdat dit gedraai het, bly bestuurders afgeskakel, ongeag wat hier gestel is, omdat vertroulike kaartjies nie uitgeken kan word nie.',
