    'self_service' => [
        'heading' => 'Selfdienportaal',
        'intro' => 'Hoe die portaal lyk vir die mense wat kaartjies skep, en wat dit hulle toelaat om te doen. Vir die meeste organisasies is die portaal die enigste deel van FreeITSM wat \'n kliënt ooit sien, so dit is die een skerm wat die moeite werd is om apart van die res te brand.',
        'appearance_heading' => 'Voorkoms',
